<?php defined('BASEPATH') OR exit('No direct script access allowed');class Developer_webhooks extends MY_Controller{private $c;private $events=array('*','workflow.run.started','workflow.run.succeeded','workflow.run.failed','workflow.run.waiting_approval','agent.task.completed','message.created','task.created','payment.received','payment.failed','subscription.changed','integration.connected','webhook.delivery_failed');function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Developer_webhook_model','hooks');}function events(){return $this->respond($this->events);}function index(){if($this->input->method(TRUE)==='POST'){$d=$this->body();if(!$this->valid($d,TRUE))return;return $this->respond($this->hooks->create($this->c['organizationId'],$this->c['sub'],$d),201);}return $this->respond($this->hooks->all($this->c['organizationId']));}function item($id){if($this->input->method(TRUE)==='DELETE'){if($this->hooks->remove($id,$this->c['organizationId'])){$this->output->set_status_header(204);return;}return $this->fail('NOT_FOUND','Webhook not found',404);}if(!$this->valid($d=$this->body(),FALSE))return;$r=$this->hooks->update_hook($id,$this->c['organizationId'],$d);return $r?$this->respond($r):$this->fail('NOT_FOUND','Webhook not found',404);}function deliveries($id){$this->load->library('Webhook_dispatcher');$this->webhook_dispatcher->retry_due($this->c['organizationId']);$r=$this->hooks->deliveries($id,$this->c['organizationId']);return $r!==NULL?$this->respond($r):$this->fail('NOT_FOUND','Webhook not found',404);}private function valid($d,$create){if($create&&!isset($d['url']))return $this->fail('VALIDATION_ERROR','URL required',422);if(isset($d['url'])&&(!filter_var($d['url'],FILTER_VALIDATE_URL)||!in_array(parse_url($d['url'],PHP_URL_SCHEME),array('http','https'),TRUE)))return $this->fail('VALIDATION_ERROR','Valid HTTP(S) URL required',422);if(isset($d['description'])&&strlen($d['description'])>500||isset($d['events'])&&!is_array($d['events']))return $this->fail('VALIDATION_ERROR','Invalid webhook input',422);return TRUE;}}
